window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["prompt-caching"]={"title":"提示缓存：复用共同前缀的 KV 计算","subtitle":"从最长共同 token 前缀、KV 占用与命中价值，到提示排序、路由亲和、失效和租户隔离。","thesis":"提示缓存跨请求复用相同 token 前缀在模型各层产生的 KV 状态，减少重复预填充。它不缓存最终答案，也不减少新后缀和输出解码；净收益由<b>命中长度 × 复用频率 × 预填充成本 − 查找/搬运/驻留代价</b>决定。","quality":{"contractVersion":2,"examples":[{"section":4,"evidence":{"setup":"系统规则 2k、工具 3k、共享政策 5k","rule":"按稳定性排序把大段共享内容放在前","steps":"0.7×10k=7k","interpretation":"真实注意力成本非线性，必须实测"}}],"formulas":[{"id":"prompt-cache-lcp","section":3,"formulaIndex":1,"symbols":[{"name":"LCP","meaning":"最长共同 token 前缀长度","evidence":"最长共同前缀计算"},{"name":"A","meaning":"第一条 token 序列","evidence":"两条 token 序列 A、B"},{"name":"B","meaning":"第二条 token 序列","evidence":"两条 token 序列 A、B"},{"name":"ℓ","meaning":"从开头连续相同的 token 数","evidence":"输出从首 token 起连续相同的长度 ℓ"}]},{"id":"prompt-cache-expected-saving","section":4,"formulaIndex":1,"symbols":[{"name":"E[Nsaved]","meaning":"每请求期望避免处理的输入 token 数","evidence":"平均节省 7k token"},{"name":"h","meaning":"缓存命中率","evidence":"h 是命中率"},{"name":"L","meaning":"命中的 token 长度","evidence":"L 是命中的 token 长度"}]},{"id":"prompt-cache-memory","section":6,"formulaIndex":1,"symbols":[{"name":"MKV","meaning":"KV 缓存总字节数","evidence":"输出 KV 字节数 MKV"},{"name":"Nlayer","meaning":"模型层数","evidence":"层数 Nlayer"},{"name":"NKVhead","meaning":"每层 KV 头数","evidence":"KV 头数 NKVhead"},{"name":"d","meaning":"每个 KV 头的维度","evidence":"头维 d"},{"name":"Ntoken","meaning":"缓存 token 数","evidence":"token 数 Ntoken"},{"name":"b","meaning":"每个数值元素的字节数","evidence":"每元素字节 b"}]}],"termReviews":[{"term":"KV 状态","section":1,"evidence":"输出可供后续请求复用的中间 KV 状态"},{"term":"最长共同前缀","section":3,"evidence":"最长共同前缀计算输入"},{"term":"缓存命名空间","section":7,"evidence":"输出缓存命名空间、键和失效动作"}],"sectionContracts":[{"section":1,"definition":{"answer":"提示缓存复用不同请求共同输入前缀的中间 KV 状态。","evidence":"提示缓存输入模型配置和多个请求共享的精确 token 前缀"},"problem":{"answer":"它减少重复的输入预填充计算并降低首 token 延迟。","evidence":"GPU 为什么还要从头处理"},"inputOutput":{"answer":"输入模型配置和精确前缀，输出可复用的 KV 状态。","evidence":"输出可供后续请求复用的中间 KV 状态"},"mechanism":{"answer":"服务命中最长前缀后只对新后缀继续预填充。","evidence":"再只计算新后缀"},"interpretation":{"answer":"命中只表示省输入计算，不表示答案已缓存或正确。","evidence":"不表示答案被缓存或输出一定正确"},"boundary":{"answer":"模型、分词、位置配置和安全域必须一致。","evidence":"只适用于模型、tokenizer、位置配置和安全域一致"}},{"section":2,"definition":{"answer":"四类缓存分别复用生成历史、输入状态、答案或工具数据。","evidence":"三种缓存不要混淆"},"problem":{"answer":"它避免用同一命中率混报不同收益和正确性风险。","evidence":"分别复用了什么"},"inputOutput":{"answer":"输入保存对象、范围和跳过阶段，输出缓存机制类别。","evidence":"输出请求内 KV、跨请求前缀、回答或应用数据缓存之一"},"mechanism":{"answer":"根据复用对象判断缓存跳过的是解码、预填充还是整个生成。","evidence":"看它复用当前生成历史、共同输入状态、最终答案还是工具结果"},"interpretation":{"answer":"不同缓存的命中具有完全不同的性能和内容含义。","evidence":"就能解释收益与正确性风险"},"boundary":{"answer":"这些机制不得共享一个未经拆分的命中率指标。","evidence":"不能共享一个命中率口径"}},{"section":3,"definition":{"answer":"LCP 是两条 token 序列从开头连续相同的最大长度。","evidence":"输出从首 token 起连续相同的长度 ℓ"},"problem":{"answer":"它解释相同文档因顺序变化为何仍可能零命中。","evidence":"顺序不同为什么仍可能命中为零"},"inputOutput":{"answer":"输入 token 序列 A 和 B，输出连续共同前缀长度。","evidence":"输入两条 token 序列 A、B"},"mechanism":{"answer":"逐 token 比较并在第一次分叉处停止复用。","evidence":"第一次分叉就停止复用"},"interpretation":{"answer":"LCP 长表示计算状态可复用，不代表语义相近。","evidence":"不代表两份提示语义更相近"},"boundary":{"answer":"影响 token、位置或模型状态的变化都会终止命中。","evidence":"都会终止命中"}},{"section":4,"definition":{"answer":"运行案例估算十二千 token 请求的命中长度与净延迟收益。","evidence":"12k 输入里究竟省了多少"},"problem":{"answer":"它展示稳定片段排序后如何计算平均节省量。","evidence":"怎样布局并估算"},"inputOutput":{"answer":"输入片段、命中率和延迟，输出命中长度、token 与延迟节省。","evidence":"输出 10k 命中长度、平均节省 7k token 及粗略延迟收益"},"mechanism":{"answer":"先稳定排序，再计算 h 乘 L 并扣除查找搬运。","evidence":"再用 h×L 求平均避免量并扣除查找搬运"},"interpretation":{"answer":"四百四十和三百零八毫秒只是给定假设下的估算。","evidence":"是给定假设下的估算"},"boundary":{"answer":"实际注意力成本非线性，因此上线收益必须实测。","evidence":"真实注意力成本必须实测"}},{"section":5,"definition":{"answer":"缓存友好布局把稳定公共内容放前、动态私有内容放后。","evidence":"提示布局与规范化决定命中"},"problem":{"answer":"它提高前缀复用而不破坏提示语义和权限。","evidence":"既提高复用，又不破坏语义和权限"},"inputOutput":{"answer":"输入稳定性、权限和语义顺序，输出确定性提示序列。","evidence":"输出稳定公共内容在前、动态私有内容在后的序列"},"mechanism":{"answer":"固定序列化和排序，使相同公共内容产生精确 token 前缀。","evidence":"确定性序列化提高精确前缀复用"},"interpretation":{"answer":"高命中只有在规则含义和隔离不变时才有价值。","evidence":"保持安全规则含义和租户隔离"},"boundary":{"answer":"不得为命中率移动或共享本应私有的内容。","evidence":"不能为提高命中率移动或共享本应私有的内容"}},{"section":6,"definition":{"answer":"KV 容量由层数、头数、头维、token、精度和并发共同决定。","evidence":"KV 容量随层、token 和并发增长"},"problem":{"answer":"它解释长前缀为何不能无限常驻昂贵的 GPU 显存。","evidence":"为什么 10k token 前缀不能无限常驻 GPU"},"inputOutput":{"answer":"输入架构与序列规模，输出 KV 字节数和存储选择。","evidence":"输出 KV 字节数 MKV 与存储层级选择"},"mechanism":{"answer":"每层每头为每个 token 保存 K 和 V，因此各维度相乘并乘二。","evidence":"K 与 V 各保存一份，所以乘二"},"interpretation":{"answer":"估算占用用于权衡 GPU 驻留、数据搬运和重新计算。","evidence":"用于比较 GPU 驻留、搬运与重算"},"boundary":{"answer":"不同架构、并行和量化会改变真实内存数值。","evidence":"架构、并行和量化不同会改变实际值"}},{"section":7,"definition":{"answer":"缓存失效用完整模型语义版本隔离不兼容的 KV 状态。","evidence":"缓存键和失效必须包含模型语义版本"},"problem":{"answer":"它防止换适配器或位置配置后静默复用错误状态。","evidence":"换了 LoRA 或 RoPE 配置还能复用吗"},"inputOutput":{"answer":"输入模型及租户版本，输出命名空间、缓存键和失效动作。","evidence":"输出缓存命名空间、键和失效动作"},"mechanism":{"answer":"任一语义配置变化即隔离缓存，并抽样重算检查污染。","evidence":"命中后抽样重算可发现污染"},"interpretation":{"answer":"相同文本在不同模型语义版本下也可能产生不同 KV。","evidence":"同一文本也可能产生不同 KV"},"boundary":{"answer":"版本字段不完整时必须拒绝复用旧状态。","evidence":"版本字段不完整时必须拒绝复用"}},{"section":8,"definition":{"answer":"KV 是输入派生的敏感状态，必须按租户和数据域治理。","evidence":"KV 虽不是可读原文，仍是输入的派生数据"},"problem":{"answer":"它防止跨租户泄露、命中侧信道和未经授权的状态复用。","evidence":"为什么仍属于敏感数据状态"},"inputOutput":{"answer":"输入数据分类、租户和保留规则，输出隔离、加密、审计和删除策略。","evidence":"输出隔离域、加密、审计与删除策略"},"mechanism":{"answer":"按安全域分区，并控制访问、保留和删除传播。","evidence":"命中时间可能泄露前缀是否存在"},"interpretation":{"answer":"不可读并不等于不敏感，时延本身也可能泄露存在性。","evidence":"仍是输入的派生数据"},"boundary":{"answer":"跨租户只共享真正公共、同权限且同版本的内容。","evidence":"只限真正公共且权限一致的版本化内容"}},{"section":9,"definition":{"answer":"缓存评测衡量节省计算减去查找、搬运、驻留和排队后的净收益。","evidence":"评测要证明净收益而非命中率"},"problem":{"answer":"它解释命中率翻倍但首 token 延迟不改善的现象。","evidence":"为什么 TTFT 可能没有改善"},"inputOutput":{"answer":"输入请求级性能、资源和质量，输出分切片净收益。","evidence":"输出按租户、长度、并发切片的净收益"},"mechanism":{"answer":"固定语义和负载做 A/B，并注入版本、冷启动和雪崩故障。","evidence":"测试错版本、冷启动和雪崩"},"interpretation":{"answer":"TTFT 不降说明命中太短或额外开销抵消了收益。","evidence":"查找、搬运、排队抵消了收益"},"boundary":{"answer":"命中率不能单独作为缓存上线或扩容依据。","evidence":"命中率升高但 TTFT 不降"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>区分请求内与跨请求 KV cache；计算最长共同前缀和收益；设计缓存友好提示布局；处理容量、失效与隐私隔离。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>重复计算发生在输入预填充<span class=\"dd-badge intuition\">直觉</span></h2><p class=\"dd-lead\">每轮 Agent 都携带相同系统规则和工具 schema，GPU 为什么还要从头处理？</p><p>自回归服务先并行处理输入 token，产生每层 K/V，再逐 token 解码。相邻请求常共享系统提示、工具定义和早期会话；跨请求前缀缓存保存这些中间张量，让新请求从共同前缀末尾继续预填充。</p><p>缓存内容不是自然语言答案，也不是语义检索结果。它只对特定模型、tokenizer、权重/适配器和位置配置下的确切 token 前缀有效。</p><div class=\"dd-note\"><b>主要收益：</b>减少输入计算、降低 TTFT、释放预填充吞吐；长输出的逐 token 解码仍原样发生。</div><p>提示缓存输入模型配置和多个请求共享的精确 token 前缀，输出可供后续请求复用的中间 KV 状态。服务先查找最长可用前缀，再只计算新后缀；命中表示省去了部分输入计算，不表示答案被缓存或输出一定正确。它只适用于模型、tokenizer、位置配置和安全域一致的请求。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>三种缓存不要混淆<span class=\"dd-badge intuition\">消歧</span></h2><p class=\"dd-lead\">请求内 KV cache、跨请求提示缓存和回答缓存分别复用了什么？</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>机制</th><th>复用范围</th><th>键/条件</th><th>改变的阶段</th></tr></thead><tbody><tr><td>请求内 KV cache</td><td>同一次生成历史 token</td><td>当前序列</td><td>逐 token 解码</td></tr><tr><td>跨请求前缀缓存</td><td>不同请求共同开头</td><td>模型+精确 token 前缀</td><td>输入预填充</td></tr><tr><td>响应/语义缓存</td><td>相同或近似问题答案</td><td>请求/语义+版本</td><td>跳过部分或全部生成</td></tr><tr><td>应用数据缓存</td><td>检索/工具结果</td><td>查询+权限+新鲜度</td><td>外部组件</td></tr></tbody></table></div><p>后两者可能返回陈旧或越权内容，正确性风险远高于纯计算状态复用。不能用“缓存命中率”一个数字混报。</p><p>缓存分类输入“被保存的对象、复用范围和跳过的阶段”，输出请求内 KV、跨请求前缀、回答或应用数据缓存之一。看它复用当前生成历史、共同输入状态、最终答案还是工具结果，就能解释收益与正确性风险；这些机制不能共享一个命中率口径。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>只有连续共同 token 前缀可直接复用<span class=\"dd-badge math\">机制</span></h2><p class=\"dd-lead\">两份提示含相同 8000 token 文档，顺序不同为什么仍可能命中为零？</p><p>因果注意力中位置 i 的表示依赖此前全部 token。中间插入时间戳会改变后续位置与上下文，因此从分叉点后的 KV 不能直接复用。</p><div class=\"dd-formula\"><math display=\"block\" aria-label=\"两条序列的最长共同前缀\"><mi>LCP</mi><mo>(</mo><mi>A</mi><mo>,</mo><mi>B</mi><mo>)</mo><mo>=</mo><munder><mi>max</mi><mi>ℓ</mi></munder><mo>{</mo><msub><mi>A</mi><mrow><mn>1</mn><mo>:</mo><mi>ℓ</mi></mrow></msub><mo>=</mo><msub><mi>B</mi><mrow><mn>1</mn><mo>:</mo><mi>ℓ</mi></mrow></msub><mo>}</mo></math></div><p>语义相同不代表 token 相同：JSON 字段顺序、空格、Unicode 规范化、模板版本和工具排序都可改变 token 序列。某些 radix-tree 系统能在许多前缀间寻找最长命中，但仍遵守精确 token 前缀条件。</p><div class=\"dd-note warn\"><b>不要把动态值放最前。</b>　请求 ID、当前时间或用户问题在开头，会让其后所有稳定内容失去复用。</div><p>最长共同前缀计算输入两条 token 序列 A、B，输出从首 token 起连续相同的长度 ℓ。系统逐 token 比较，第一次分叉就停止复用；LCP 较长只说明计算状态可复用，不代表两份提示语义更相近。任何影响 token、位置或模型状态的变化都会终止命中。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>运行示例：12k 输入里究竟省了多少<span class=\"dd-badge math\">逐步演算</span></h2><p class=\"dd-lead\">系统规则 2k、工具 3k、共享政策 5k、会话 1k、当前问题 1k，怎样布局并估算？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 710 260\" role=\"img\" aria-label=\"十二千 token 提示按稳定性排序形成十千 token 缓存命中与两千 token 新后缀\"><rect x=\"18\" y=\"74\" width=\"112\" height=\"58\" rx=\"7\" fill=\"#4f9d78\"/><text x=\"74\" y=\"99\" text-anchor=\"middle\" class=\"svg-t\">系统 2k</text><text x=\"74\" y=\"119\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">稳定</text><rect x=\"130\" y=\"74\" width=\"140\" height=\"58\" fill=\"#4f9d78\"/><text x=\"200\" y=\"99\" text-anchor=\"middle\" class=\"svg-t\">工具 3k</text><text x=\"200\" y=\"119\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">稳定</text><rect x=\"270\" y=\"74\" width=\"206\" height=\"58\" fill=\"#4f9d78\"/><text x=\"373\" y=\"99\" text-anchor=\"middle\" class=\"svg-t\">共享政策 5k</text><text x=\"373\" y=\"119\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">版本 p17</text><rect x=\"476\" y=\"74\" width=\"100\" height=\"58\" fill=\"#d3a05a\"/><text x=\"526\" y=\"99\" text-anchor=\"middle\" class=\"svg-t\">历史 1k</text><text x=\"526\" y=\"119\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">动态</text><rect x=\"576\" y=\"74\" width=\"116\" height=\"58\" rx=\"7\" fill=\"#c77b72\"/><text x=\"634\" y=\"99\" text-anchor=\"middle\" class=\"svg-t\">问题 1k</text><text x=\"634\" y=\"119\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">每次不同</text><path d=\"M18,151 L476,151\" stroke=\"#4f9d78\" stroke-width=\"5\"/><text x=\"247\" y=\"178\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">命中前缀 10k：直接复用 KV</text><path d=\"M476,151 L692,151\" stroke=\"#d3a05a\" stroke-width=\"5\"/><text x=\"584\" y=\"178\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">新后缀 2k：仍需 prefill</text><text x=\"355\" y=\"220\" text-anchor=\"middle\" class=\"svg-t\">若命中率 70%，平均避免处理约 0.7×10k=7k input token/请求</text></svg><figcaption>图 1　按稳定性排序把大段共享内容放在前，动态历史与问题放后，最长共同前缀才有机会达到 10k。</figcaption></figure><div class=\"dd-formula\"><math display=\"block\" aria-label=\"期望避免处理的输入 token 数\"><mi>E[Nsaved]</mi><mo>≈</mo><mi>h</mi><mo>×</mo><mi>L</mi><mo>=</mo><mn>0.7</mn><mo>×</mo><mn>10000</mn><mo>=</mo><mn>7000</mn></math></div><p>若无缓存 TTFT 中预填充 600ms，命中后 10k/12k 计算可省但有 60ms 查找/搬运，粗略命中请求约 <code>600×(10/12)−60=440ms</code>；全流量期望约 308ms。真实注意力成本非线性，必须实测。</p><p>案例输入 12k token 的稳定与动态片段、70% 命中率和预填充延迟，输出 10k 命中长度、平均节省 7k token 及粗略延迟收益。h 是命中率，L 是命中的 token 长度；先按稳定性排布，再用 h×L 求平均避免量并扣除查找搬运。440ms 和 308ms 是给定假设下的估算，真实注意力成本必须实测。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>提示布局与规范化决定命中<span class=\"dd-badge eng\">工程</span></h2><p class=\"dd-lead\">怎样组织上下文既提高复用，又不破坏语义和权限？</p><ol class=\"dd-steps\"><li>最前放模型/应用版本稳定的系统规则。</li><li>随后放排序固定的工具 schema 和共享少样本。</li><li>再放版本化公共文档或政策。</li><li>后部放会话历史、检索证据和当前输入。</li><li>时间戳、随机 nonce、trace id 留在不参与模型的元数据或末尾。</li></ol><p>确定性序列化对象，固定字段与工具顺序、空白和 Unicode 规范。不能为了命中把用户特定权限或秘密提升为共享前缀；性能优化服从数据边界。</p><div class=\"dd-note warn\"><b>语义顺序也重要。</b>　把安全规则移到前面有利缓存，但若模板语义改变必须重新评测，不能只按命中率重排。</div><p>提示布局输入各片段的稳定性、权限域和语义顺序，输出稳定公共内容在前、动态私有内容在后的序列。确定性序列化提高精确前缀复用，但结果必须同时保持安全规则含义和租户隔离。不能为提高命中率移动或共享本应私有的内容。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>KV 容量随层、token 和并发增长<span class=\"dd-badge math\">内存</span></h2><p class=\"dd-lead\">为什么 10k token 前缀不能无限常驻 GPU？</p><p>粗略 KV 字节数与 <code>2×层数×KV头数×头维×token数×每元素字节</code>成正比；2 表示 K 与 V。以 32 层、8 KV 头、128 维、FP16、10k token：</p><div class=\"dd-formula\"><math display=\"block\" aria-label=\"KV 缓存字节数估算\"><mi>MKV</mi><mo>≈</mo><mn>2</mn><mo>×</mo><mi>Nlayer</mi><mo>×</mo><mi>NKVhead</mi><mo>×</mo><mi>d</mi><mo>×</mo><mi>Ntoken</mi><mo>×</mo><mi>b</mi><mo>≈</mo><mn>1.31</mn><mi>GB</mi></math></div><p>不同架构、张量并行和量化会改变数字，但规模说明缓存会与模型权重和活跃请求争显存。使用分块/PagedAttention、前缀树、TTL、LRU 或按“节省计算/占用字节”价值淘汰；搬到 CPU/远端会增加延迟与带宽。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>策略</th><th>优点</th><th>代价</th></tr></thead><tbody><tr><td>GPU 常驻</td><td>命中最快</td><td>昂贵、挤压并发</td></tr><tr><td>CPU/远端层级</td><td>容量大</td><td>搬运可能超过重算</td></tr><tr><td>TTL/LRU</td><td>简单</td><td>不理解前缀价值</td></tr><tr><td>价值感知</td><td>保留长且热门前缀</td><td>估值和实现复杂</td></tr></tbody></table></div><p>容量规划输入层数 Nlayer、KV 头数 NKVhead、头维 d、token 数 Ntoken、每元素字节 b 和并发，输出 KV 字节数 MKV 与存储层级选择。K 与 V 各保存一份，所以乘二；估算占用用于比较 GPU 驻留、搬运与重算，但架构、并行和量化不同会改变实际值。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>缓存键和失效必须包含模型语义版本<span class=\"dd-badge eng\">正确性</span></h2><p class=\"dd-lead\">文本前缀没变，换了 LoRA 或 RoPE 配置还能复用吗？</p><p>不能假定。权重/适配器、tokenizer、位置编码、注意力实现、精度、模型模板和可能影响隐藏状态的推理配置变化都需进入 namespace 或使缓存失效。提示、工具和政策版本变更也改变 token。</p><p>缓存键通常包含模型快照、适配器、token 序列哈希、租户/安全域与位置起点；命中后可抽样重算对比，捕获实现错误。滚动发布时新旧缓存隔离，不能让 v42 读取 v41 状态。</p><div class=\"dd-note warn\"><b>缓存污染会静默传播。</b>　错误状态被高频复用，比单次推理错误影响更大；需校验哈希、版本和快速全量失效开关。</div><p>失效设计输入模型快照、适配器、tokenizer、位置配置、模板和租户域，输出缓存命名空间、键和失效动作。只要其中一项改变，同一文本也可能产生不同 KV；命中后抽样重算可发现污染。版本字段不完整时必须拒绝复用，而不是冒险读旧状态。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>隐私、租户隔离与侧信道<span class=\"dd-badge eng\">安全</span></h2><p class=\"dd-lead\">KV 不是可读文本，为什么仍属于敏感数据状态？</p><p>KV 是输入的派生表示，可能包含敏感信息；跨租户共享还可能通过命中延迟推测某前缀是否存在，或因键缺少权限字段复用不应共享内容。默认按租户/组织/数据分类隔离，公共系统前缀与用户私有历史分开。</p><p>设置保留期、加密、访问审计和删除传播；日志只记录前缀哈希/长度而非原文。共享公共政策也要确认所有租户有相同版本和访问权。服务供应商缓存政策属于数据处理协议的一部分。</p><div class=\"dd-note warn\"><b>不要用用户可控前缀直接寻址共享缓存。</b>　需要域隔离、完整哈希和长度/配额限制，防碰撞、探测与资源耗尽。</div><p>安全治理输入前缀的数据分类、租户、保留期和访问权，输出隔离域、加密、审计与删除策略。KV 虽不是可读原文，仍是输入的派生数据，且命中时间可能泄露前缀是否存在。跨租户共享只限真正公共且权限一致的版本化内容。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">9</span>评测要证明净收益而非命中率<span class=\"dd-badge intuition\">评测</span></h2><p class=\"dd-lead\">命中率从 40% 升到 80%，为什么 TTFT 可能没有改善？</p><p>可能只命中很短前缀，查找/跨机搬运超过重算，或路由到缓存节点增加排队。测请求级命中长度分布、节省 prefill token/时间、查找/搬运、GPU KV 占用、驱逐、TTFT p50/p95/p99、吞吐、费用和质量。</p><p>A/B 必须保持提示语义和路由负载可比；按租户、长度和并发切片。故障测试版本错配、节点丢失、缓存雪崩、冷启动、删除和跨租户访问。</p><div class=\"dd-note\"><b>价值指标：</b>每 GB·小时缓存带来的 TTFT/计算节省，以及在 SLO 下增加的可服务吞吐，比裸命中率更接近决策。</div><p>缓存评测输入请求级命中长度、计算与搬运时间、显存、延迟、吞吐和质量，输出按租户、长度、并发切片的净收益。A/B 固定提示语义与路由负载，并测试错版本、冷启动和雪崩；命中率升高但 TTFT 不降，通常说明命中太短或查找、搬运、排队抵消了收益。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">10</span>常见误区与概念依赖<span class=\"dd-badge intuition\">常见误区与学习路线</span></h2><p class=\"dd-lead\">提示缓存是带版本和安全域的计算状态复用，不是“记住答案”。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>缓存保存模型答案</td><td>提示缓存保存共同前缀的层级 KV 状态</td></tr><tr><td>包含相同文本就能命中</td><td>必须从首 token 连续相同且配置一致</td></tr><tr><td>命中会减少输出计算</td><td>主要省输入 prefill，新后缀与 decode 仍需算</td></tr><tr><td>命中率越高越好</td><td>还要看长度、搬运、驻留和排队净收益</td></tr><tr><td>KV 不可读所以不敏感</td><td>它是输入派生数据，需隔离、保留和删除治理</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>概念依赖与延伸学习</th></tr></thead><tbody><tr><td>先修</td><td>self-attention、KV cache、tokenization、prefill/decode</td></tr><tr><td><b>本页核心</b></td><td>LCP、前缀布局、KV 容量、路由亲和、失效隔离</td></tr><tr><td>性能</td><td>推理优化、部署、流式输出</td></tr><tr><td>上下文</td><td>上下文工程、响应预填充、隐私与可观测性</td></tr></tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">11</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>测量 prefill 占比与重复前缀</li><li>按稳定性和权限重排上下文</li><li>用配置/租户/token 前缀构建键</li><li>价值感知存储与路由命中</li><li>版本变化原子失效</li><li>用命中长度/TTFT/显存/质量联合验收</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">12</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>12k 示例平均避免多少 input token？</li><li>为何时间戳放前面会破坏命中？</li><li>10k 示例 KV 粗略多大？</li><li>换 LoRA 后为何要失效？</li><li>为何不能只看命中率？</li><li>假设“提示缓存：复用共同前缀的 KV 计算”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li><li>如何为“提示缓存：复用共同前缀的 KV 计算”设计一个最小对照实验，证明观察到的改善来自核心机制，而不是数据、提示、权限或评测口径同时变化？</li><li>为什么不能只用一个平均分判断“提示缓存：复用共同前缀的 KV 计算”已经可靠？应怎样按场景切片并设置失败边界？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>命中率 70% 且命中 10k，平均约 7k token/请求。</li><li>从分叉 token 起后续所有位置与 KV 都不同。</li><li>给定 32 层、8 KV 头、128 维、FP16 时约 1.31GB。</li><li>权重改变，同一 token 前缀产生不同隐藏/KV 状态。</li><li>短命中、搬运、驻留和排队可能让净收益为零或负。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li><li>固定数据、模型版本、提示、权限、预算和评测，只改变一个与核心机制直接相关的因素，并在多个样本与随机种子上重复；同时保存中间状态和失败样本。若差异只在目标因素变化时稳定出现，才支持机制解释，否则应继续排查混杂变量。</li><li>平均分会隐藏少数类别、极端输入、成本、延迟和安全失败。至少按难度、输入类型、长度或规模、风险等级及已知边界切片，同时报告质量、资源和失败率；高风险硬约束不能被其他切片的高分抵消。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/2309.06180\" target=\"_blank\" rel=\"noopener\">vLLM: Easy, Fast, and Cheap LLM Serving with PagedAttention</a>：KV cache 分页与服务</li><li><a href=\"https://arxiv.org/abs/2312.07104\" target=\"_blank\" rel=\"noopener\">SGLang</a>：RadixAttention 与共享前缀复用</li><li><a href=\"https://arxiv.org/abs/2407.00023\" target=\"_blank\" rel=\"noopener\">Preble</a>：前缀感知分布式调度</li><li><a href=\"https://arxiv.org/abs/2311.04934\" target=\"_blank\" rel=\"noopener\">Prompt Cache</a>：长提示模块复用</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
